CREATE DATABASE IF NOT EXISTS job_sprout DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE job_sprout;

CREATE TABLE IF NOT EXISTS sys_user (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL,
  real_name VARCHAR(50), phone VARCHAR(20), email VARCHAR(100), role VARCHAR(20) NOT NULL DEFAULT 'STUDENT',
  avatar VARCHAR(255), status TINYINT NOT NULL DEFAULT 1, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS student_info (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, school VARCHAR(100), major VARCHAR(100), education VARCHAR(30), graduation_year INT,
  skills VARCHAR(500), introduction VARCHAR(1000), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS company_info (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, company_name VARCHAR(100) NOT NULL, industry VARCHAR(50), address VARCHAR(255), description VARCHAR(1000), logo VARCHAR(255), audit_status VARCHAR(20) DEFAULT 'PENDING', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS job_category (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(50) NOT NULL, sort INT DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS job (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, company_id BIGINT NOT NULL, category_id BIGINT, title VARCHAR(100) NOT NULL, description TEXT, requirements TEXT, salary_min INT, salary_max INT, city VARCHAR(50), experience VARCHAR(50), education VARCHAR(30), status VARCHAR(20) DEFAULT 'DRAFT', publish_time DATETIME, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS resume (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, phone VARCHAR(20), email VARCHAR(100), education VARCHAR(30), experience TEXT, skills VARCHAR(500), attachment_url VARCHAR(255), is_default TINYINT DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS job_apply (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, job_id BIGINT NOT NULL, resume_id BIGINT NOT NULL, student_id BIGINT NOT NULL, company_id BIGINT NOT NULL, status VARCHAR(20) DEFAULT 'SUBMITTED', remark VARCHAR(500), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS message (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, sender_id BIGINT NOT NULL, receiver_id BIGINT NOT NULL, content VARCHAR(2000) NOT NULL, message_type VARCHAR(20) DEFAULT 'TEXT', is_read TINYINT DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO sys_user (username,password,real_name,role) VALUES
 ('student01','123456','张同学','STUDENT'),('company01','123456','职芽科技','COMPANY'),('admin','123456','系统管理员','ADMIN')
ON DUPLICATE KEY UPDATE username=username;
INSERT INTO job_category (name,sort) VALUES ('Java开发',1),('前端开发',2),('产品运营',3),('实习岗位',4)
ON DUPLICATE KEY UPDATE name=name;
INSERT INTO student_info (user_id,school,major,education,graduation_year) SELECT id,'示例大学','软件工程','本科',2027 FROM sys_user WHERE username='student01' AND NOT EXISTS (SELECT 1 FROM student_info);
INSERT INTO company_info (user_id,company_name,industry,address,audit_status) SELECT id,'职芽科技有限公司','互联网','上海','APPROVED' FROM sys_user WHERE username='company01' AND NOT EXISTS (SELECT 1 FROM company_info);
INSERT INTO job (company_id,category_id,title,description,requirements,salary_min,salary_max,city,status,publish_time) SELECT c.id,1,'Java开发实习生','参与后端服务开发，协助完成接口设计与测试。','熟悉 Java，了解 Spring Boot，有良好学习能力。',3000,5000,'上海','PUBLISHED',NOW() FROM company_info c WHERE c.company_name='职芽科技有限公司' AND NOT EXISTS (SELECT 1 FROM job);
